{
  "schemaVersion": 1,
  "query": "Local/self-hosted MCP server exposing web search and web page fetch to a coding agent (Claude Code), free-tier or own API key, stdio, personal laptop use.",
  "fingerprint": {
    "mustHaveCapabilities": [
      "web search",
      "web page fetch",
      "local stdio MCP server",
      "own or free-tier API key"
    ],
    "capabilityAliases": {
      "web search": ["search the web", "internet search", "query engine", "DuckDuckGo search", "Brave search", "Tavily search"],
      "web page fetch": ["fetch URL", "read web page", "scrape page", "convert HTML to markdown", "extract content"],
      "local stdio MCP server": ["stdio MCP server", "local MCP server", "self-hosted MCP", "runs on laptop"],
      "own or free-tier API key": ["user API key", "free API tier", "no API key", "keyless", "BYO key"]
    },
    "desiredOutcome": "A coding agent can look up web content mid-task via a server the user hosts locally and controls with their own key.",
    "operatingMode": "local stdio MCP server, personal laptop, Claude Code client"
  },
  "retrievals": [
    {
      "requestId": "registry-discovery-1",
      "providerHint": "mcp-registry",
      "categoryHint": "registry",
      "outcome": "success",
      "payload": {
        "query": "fetch",
        "servers": [
          {"name": "ai.clawfetch/mcp", "description": "Web intelligence for AI agents: fetch, render, extract, research. x402 micropayments, no API keys.", "repo": "github.com/clawfetch/clawfetch-mcp", "transport": "stdio", "env": [{"name": "CLAWFETCH_PRIVATE_KEY", "required": true}]},
          {"name": "ai.smithery/arjunkmrm-fetch", "description": "Fetch web pages and extract exactly the content."}
        ]
      }
    },
    {
      "requestId": "registry-discovery-2",
      "providerHint": "mcp-registry",
      "categoryHint": "registry",
      "outcome": "success",
      "payload": {
        "query": "brave",
        "servers": [
          {"name": "ai.smithery/brave", "description": "Brave Search API; free API key.", "repo": "github.com/brave/brave-search-mcp-server"},
          {"name": "ai.smithery/arjunkmrm-brave-search-mcp-server", "description": "Search the web, images, videos, news."}
        ]
      }
    },
    {
      "requestId": "registry-discovery-3",
      "providerHint": "mcp-registry",
      "categoryHint": "registry",
      "outcome": "success",
      "payload": {
        "query": "tavily",
        "servers": [
          {"name": "io.github.Seey215/tavily-mcp", "repo": "github.com/Seey215/tavily-mcp", "transport": "stdio", "env": [{"name": "TAVILY_API_KEY", "required": true}]}
        ]
      }
    },
    {
      "requestId": "registry-discovery-4",
      "providerHint": "mcp-registry",
      "categoryHint": "registry",
      "outcome": "success",
      "payload": {
        "query": "serper",
        "servers": [
          {"name": "io.github.pipeworx-io/serper", "description": "Wraps the Serper Google Search API (serper.dev)", "repo": "github.com/pipeworx-io/mcp-serper", "transport": "streamable-http remote"}
        ]
      }
    },
    {
      "requestId": "npm-discovery-1",
      "providerHint": "npm",
      "categoryHint": "registry",
      "outcome": "success",
      "payload": {
        "query": "mcp web search",
        "packages": [
          {"name": "@zhafron/mcp-web-search", "version": "1.3.0", "license": "MIT", "description": "Multi-provider web search (DuckDuckGo, Bing, SearXNG) with automatic fallback, and URL content extraction — no API keys required.", "repo": "github.com/tickernelz/mcp-web-search"},
          {"name": "firecrawl-mcp", "version": "3.24.0", "license": "MIT", "description": "Firecrawl search, scrape; supports cloud and self-hosted instances.", "repo": "github.com/firecrawl/firecrawl-mcp-server"},
          {"name": "@brave/brave-search-mcp-server", "version": "2.1.3", "license": "MIT", "description": "Brave Search MCP Server: web results, images, videos, AI summaries.", "repo": "github.com/brave/brave-search-mcp-server"},
          {"name": "@antmanler/websearch-mcp", "version": "0.2.2", "license": "MIT", "description": "Go-based MCP web search server"},
          {"name": "mcp-web-search", "version": "1.0.12", "license": "ISC", "description": "MCP Web Search Server (stdio) - Web/papers/patents search", "repo": "github.com/QunaSys/mcp-web-search"}
        ]
      }
    },
    {
      "requestId": "npm-discovery-2",
      "providerHint": "npm",
      "categoryHint": "registry",
      "outcome": "success",
      "payload": {
        "query": "tavily mcp",
        "packages": [
          {"name": "tavily-mcp", "version": "0.2.22", "license": "MIT", "description": "MCP server for advanced web search using Tavily; search, extract, map, crawl tools.", "repo": "github.com/tavily-ai/tavily-mcp"}
        ]
      }
    },
    {
      "requestId": "npm-discovery-3",
      "providerHint": "npm",
      "categoryHint": "registry",
      "outcome": "success",
      "payload": {
        "query": "mcp server fetch",
        "packages": [
          {"name": "defuddle-stdio-mcp", "version": "1.0.0", "license": "MIT", "description": "stdio MCP server: fetch a URL and extract clean markdown with Defuddle"},
          {"name": "mcp-server-fetch-typescript", "version": "0.1.1", "license": "MIT", "description": "MCP server that provides web content fetching and conversion", "repo": "github.com/tatn/mcp-server-fetch-typescript"},
          {"name": "@zenrows/mcp", "version": "2.2.0", "license": "MIT", "description": "Zenrows MCP server — Fetch, Extract, Batch, and Browser Sessions"}
        ]
      }
    },
    {
      "requestId": "github-search-1",
      "providerHint": "github",
      "categoryHint": "repo",
      "outcome": "success",
      "payload": {
        "query": "mcp web search server",
        "repos": [
          {"full_name": "MODSetter/SurfSense", "stars": 16030, "description": "Open-source NotebookLM alternative. Research the open web through platform, API or MCP server."},
          {"full_name": "firecrawl/firecrawl-mcp-server", "stars": 7342, "description": "Official Firecrawl MCP Server - web scraping and search for Cursor, Claude, LLM clients."},
          {"full_name": "exa-labs/exa-mcp-server", "stars": 4941, "description": "Exa MCP for web search and web crawling."},
          {"full_name": "anysearch-ai/anysearch-mcp-server", "stars": 1839, "description": "Unified real-time search MCP server with batch search and URL content extraction."},
          {"full_name": "Aas-ee/open-webSearch", "stars": 1761, "description": "Multi-engine MCP server, CLI, local daemon for agent web search; no API keys."},
          {"full_name": "nickclyde/duckduckgo-mcp-server", "stars": 1442, "description": "MCP server for web search through DuckDuckGo, plus content fetching and parsing."},
          {"full_name": "mrkrsl/web-search-mcp", "stars": 1113, "description": "A simple, locally hosted Web Search MCP server for use with Local LLMs"}
        ]
      }
    },
    {
      "requestId": "github-readme-1",
      "providerHint": "github",
      "categoryHint": "repo",
      "outcome": "success",
      "payload": {
        "repo": "modelcontextprotocol/servers (src/fetch)",
        "findings": "Official reference Fetch MCP server. Python (mcp>=1.29.0,<2). Tool: fetch(url, max_length, start_index, raw). Converts HTML to markdown. stdio. Can access local/internal IPs (security caution). Install via uvx mcp-server-fetch."
      }
    },
    {
      "requestId": "github-readme-2",
      "providerHint": "github",
      "categoryHint": "repo",
      "outcome": "success",
      "payload": {
        "repo": "brave/brave-search-mcp-server",
        "findings": "Official Brave Search MCP server. TypeScript/npm. STDIO default (2.x). Tools: brave_web_search, brave_local_search, brave_video_search, brave_image_search, brave_news_search. Requires BRAVE_API_KEY. Free $5/month credit (~1000 search requests)."
      }
    },
    {
      "requestId": "github-readme-3",
      "providerHint": "github",
      "categoryHint": "repo",
      "outcome": "success",
      "payload": {
        "repo": "tavily-ai/tavily-mcp",
        "findings": "Official Tavily MCP server. TypeScript/npm. Tools: search, extract, map, crawl. STDIO local OR remote MCP (https://mcp.tavily.com/mcp). Requires TAVILY_API_KEY. Free 'Researcher' plan: 1000 credits/month, no credit card. Explicit Claude Code instructions via 'claude mcp add'."
      }
    },
    {
      "requestId": "github-readme-4",
      "providerHint": "github",
      "categoryHint": "repo",
      "outcome": "success",
      "payload": {
        "repo": "tickernelz/mcp-web-search (@zhafron/mcp-web-search)",
        "findings": "Node 18+ stdio MCP. Tools: search_web (DuckDuckGo/Bing/SearXNG fallback), fetch_url (HTML/PDF/text/markdown/JSON, max_length pagination). NO paid API required. SSRF protection. Claude Code config provided."
      }
    },
    {
      "requestId": "github-readme-5",
      "providerHint": "github",
      "categoryHint": "repo",
      "outcome": "success",
      "payload": {
        "repo": "nickclyde/duckduckgo-mcp-server",
        "findings": "Python stdio MCP (uvx). Tools: web search via DuckDuckGo, content fetching/parsing. Built-in rate limiting. No API key. Claude Desktop config provided."
      }
    },
    {
      "requestId": "github-readme-6",
      "providerHint": "github",
      "categoryHint": "repo",
      "outcome": "success",
      "payload": {
        "repo": "Aas-ee/open-webSearch",
        "findings": "MCP server + CLI + local daemon. Multi-engine (bing/baidu/duckduckgo/exa/brave/startpage/sogou/hackernews). No API keys. HTTP proxy support. Article fetch (csdn/github README/generic HTTP). Chinese + English README."
      }
    },
    {
      "requestId": "web-pricing-1",
      "providerHint": "host-web",
      "categoryHint": "web",
      "outcome": "success",
      "payload": {
        "source": "https://api-dashboard.search.brave.com/documentation/pricing",
        "findings": "Brave Search API: no separate free tier; every paid plan includes free $5 in credits/month, automatically applied. Search plan $5 per 1000 requests. Effectively ~1000 free search requests/month via the credit."
      }
    },
    {
      "requestId": "web-pricing-2",
      "providerHint": "host-web",
      "categoryHint": "web",
      "outcome": "success",
      "payload": {
        "source": "https://tavily.com/pricing",
        "findings": "Tavily free 'Researcher' plan: $0/month, 1000 API credits/month, no credit card, resets first of month. Pay As You Go: $0.008 per credit."
      }
    }
  ],
  "topK": 8
}

